/**
 * Written from the Redis documentation and observable behaviour; no Redis source code was consulted.
 */
import type { Reply } from '@/libs/resp';
import { NULL_ARRAY, RespError } from '@/libs/resp';

/**
 * Keyspace notifications (notify-keyspace-events), the way Redis emits them from each command.
 *
 * Redis calls notifyKeyspaceEvent() inside the command implementations; here the same events are derived after the
 * command ran, from its arguments, its reply and which keys existed before / after. Event names, classes and order
 * follow the "Events generated by different commands" table of the Redis keyspace notifications docs.
 *
 * Classes: g generic, $ string, l list, s set, h hash, z sorted set, t stream, x expired, e evicted, n new key, m key miss.
 */

export interface KeyEvent {
  /** Event class character. */
  cls: string;
  event: string;
  key: string;
  /** Database the event belongs to when it is not the command's own (MOVE / COPY … DB). */
  db?: number;
}

/** What the server knows about one execution, for deriving events. */
export interface Execution {
  name: string;
  args: string[];
  reply: Reply;
  /** Keys that existed before the command, by name. */
  existedBefore: (key: string) => boolean;
  /** Keys that exist after the command. */
  existsAfter: (key: string) => boolean;
  /** Keys whose TTL was set by the command (EX/PX/… options), for the extra `expire` event. */
  hadTtlOption?: boolean;
  /** Number of elements of a key before / after the command (streams: entries), when known. */
  sizeBefore?: (key: string) => number;
  sizeAfter?: (key: string) => number;
}

const ev = (cls: string, event: string, key: string, db?: number): KeyEvent => (db === undefined ? { cls, event, key } : { cls, event, key, db });

/**
 * Whether SET stored its value. Without GET the reply tells (OK / null); with GET the reply is the old value, so the
 * NX / XX condition is evaluated against whether the key existed before.
 */
export function setWrote(args: readonly string[], reply: Reply, existedBefore: boolean): boolean {
  if (reply instanceof RespError) return false;
  const opts = args.slice(2).map((a) => a.toLowerCase());
  if (!opts.includes('get')) return reply !== null;
  if (opts.includes('nx')) return !existedBefore;
  if (opts.includes('xx')) return existedBefore;
  return true;
}

function ok(reply: Reply): boolean {
  return !(reply instanceof RespError) && reply !== null && reply !== NULL_ARRAY;
}

function positive(reply: Reply): boolean {
  if (Array.isArray(reply) && reply.length === 0) return false;
  return typeof reply === 'number' ? reply > 0 : typeof reply === 'bigint' ? reply > 0n : ok(reply);
}

/** A key emptied by the command gets a generic `del` after the type event. */
function withDel(events: KeyEvent[], x: Execution, key: string): KeyEvent[] {
  if (x.existedBefore(key) && !x.existsAfter(key)) events.push(ev('g', 'del', key));
  return events;
}

function ttlOption(args: string[], from: number): boolean {
  return args.slice(from).some((a) => /^(ex|px|exat|pxat)$/i.test(a));
}

type Emitter = (x: Execution) => KeyEvent[];

const same = (cls: string, event: string): Emitter => (x) => (positive(x.reply) ? withDel([ev(cls, event, x.args[0])], x, x.args[0]) : []);

const EMITTERS: Record<string, Emitter> = {
  // ---- generic ----
  del: (x) => x.args.filter((k) => x.existedBefore(k) && !x.existsAfter(k)).map((k) => ev('g', 'del', k)),
  unlink: (x) => x.args.filter((k) => x.existedBefore(k) && !x.existsAfter(k)).map((k) => ev('g', 'del', k)),
  rename: (x) => (ok(x.reply) ? [ev('g', 'rename_from', x.args[0]), ev('g', 'rename_to', x.args[1])] : []),
  renamenx: (x) => (x.reply === 1 ? [ev('g', 'rename_from', x.args[0]), ev('g', 'rename_to', x.args[1])] : []),
  move: (x) => (x.reply === 1 ? [ev('g', 'move_from', x.args[0]), ev('g', 'move_to', x.args[0], Number(x.args[1]))] : []),
  copy: (x) => {
    if (x.reply !== 1) return [];
    const i = x.args.findIndex((a, j) => j >= 2 && a.toLowerCase() === 'db');
    return [ev('g', 'copy_to', x.args[1], i >= 0 ? Number(x.args[i + 1]) : undefined)];
  },
  restore: (x) => (ok(x.reply) ? [ev('g', 'restore', x.args[0])] : []),
  expire: (x) => expireEvents(x),
  pexpire: (x) => expireEvents(x),
  expireat: (x) => expireEvents(x),
  pexpireat: (x) => expireEvents(x),
  persist: (x) => (x.reply === 1 ? [ev('g', 'persist', x.args[0])] : []),
  sort: (x) => {
    const i = x.args.findIndex((a) => a.toLowerCase() === 'store');
    if (i < 0) return [];
    const dst = x.args[i + 1];
    return x.existsAfter(dst) ? [ev('l', 'sortstore', dst)] : x.existedBefore(dst) ? [ev('g', 'del', dst)] : [];
  },

  // ---- strings ----
  set: (x) => {
    if (!setWrote(['set', ...x.args], x.reply, x.existedBefore(x.args[0]))) return [];
    if (!x.existsAfter(x.args[0])) return [];
    const out = [ev('$', 'set', x.args[0])];
    if (ttlOption(x.args, 2)) out.push(ev('g', 'expire', x.args[0]));
    return out;
  },
  setex: (x) => (ok(x.reply) ? [ev('$', 'set', x.args[0]), ev('g', 'expire', x.args[0])] : []),
  psetex: (x) => (ok(x.reply) ? [ev('$', 'set', x.args[0]), ev('g', 'expire', x.args[0])] : []),
  setnx: (x) => (x.reply === 1 ? [ev('$', 'set', x.args[0])] : []),
  getset: (x) => (ok(x.reply) || x.reply === null ? [ev('$', 'set', x.args[0])] : []),
  mset: (x) => x.args.filter((_, i) => i % 2 === 0).map((k) => ev('$', 'set', k)),
  msetnx: (x) => (x.reply === 1 ? x.args.filter((_, i) => i % 2 === 0).map((k) => ev('$', 'set', k)) : []),
  getdel: (x) => (ok(x.reply) ? [ev('g', 'del', x.args[0])] : []),
  getex: (x) => {
    if (!ok(x.reply) || x.args.length < 2) return [];
    return [ev('g', x.args[1].toLowerCase() === 'persist' ? 'persist' : 'expire', x.args[0])];
  },
  setrange: (x) => (x.existsAfter(x.args[0]) && x.args[2] !== '' ? [ev('$', 'setrange', x.args[0])] : []),
  incr: (x) => (ok(x.reply) ? [ev('$', 'incrby', x.args[0])] : []),
  // the docs: "INCR, DECR, INCRBY, DECRBY commands all generate incrby events"
  decr: (x) => (ok(x.reply) ? [ev('$', 'incrby', x.args[0])] : []),
  incrby: (x) => (ok(x.reply) ? [ev('$', 'incrby', x.args[0])] : []),
  decrby: (x) => (ok(x.reply) ? [ev('$', 'incrby', x.args[0])] : []),
  incrbyfloat: (x) => (ok(x.reply) ? [ev('$', 'incrbyfloat', x.args[0])] : []),
  append: (x) => (ok(x.reply) ? [ev('$', 'append', x.args[0])] : []),
  setbit: (x) => (ok(x.reply) ? [ev('$', 'setbit', x.args[0])] : []),
  bitop: (x) => (x.existsAfter(x.args[1]) ? [ev('$', 'set', x.args[1])] : x.existedBefore(x.args[1]) ? [ev('g', 'del', x.args[1])] : []),
  bitfield: (x) => (x.args.slice(1).some((a) => /^(set|incrby)$/i.test(a)) && x.existsAfter(x.args[0]) ? [ev('$', 'setbit', x.args[0])] : []),
  pfadd: (x) => (x.reply === 1 ? [ev('$', 'pfadd', x.args[0])] : []),
  pfmerge: (x) => (ok(x.reply) ? [ev('$', 'pfadd', x.args[0])] : []),

  // ---- lists ----
  lpush: same('l', 'lpush'),
  rpush: same('l', 'rpush'),
  lpushx: same('l', 'lpush'),
  rpushx: same('l', 'rpush'),
  lpop: same('l', 'lpop'),
  rpop: same('l', 'rpop'),
  blpop: (x) => popEvents(x, 'l', 'lpop'),
  brpop: (x) => popEvents(x, 'l', 'rpop'),
  lmpop: (x) => mpopEvents(x, 'l', (a) => (a.toLowerCase() === 'left' ? 'lpop' : 'rpop'), 1),
  blmpop: (x) => mpopEvents(x, 'l', (a) => (a.toLowerCase() === 'left' ? 'lpop' : 'rpop'), 2),
  linsert: (x) => (typeof x.reply === 'number' && x.reply > 0 ? [ev('l', 'linsert', x.args[0])] : []),
  lset: (x) => (ok(x.reply) ? [ev('l', 'lset', x.args[0])] : []),
  lrem: same('l', 'lrem'),
  ltrim: (x) => (ok(x.reply) && x.existedBefore(x.args[0]) ? withDel([ev('l', 'ltrim', x.args[0])], x, x.args[0]) : []),
  rpoplpush: (x) => moveEvents(x, 'rpop', 'lpush'),
  brpoplpush: (x) => moveEvents(x, 'rpop', 'lpush'),
  lmove: (x) => moveEvents(x, `${x.args[2].toLowerCase() === 'left' ? 'l' : 'r'}pop`, `${x.args[3].toLowerCase() === 'left' ? 'l' : 'r'}push`),
  blmove: (x) => moveEvents(x, `${x.args[2].toLowerCase() === 'left' ? 'l' : 'r'}pop`, `${x.args[3].toLowerCase() === 'left' ? 'l' : 'r'}push`),

  // ---- hashes ----
  hset: same('h', 'hset'),
  hmset: (x) => (ok(x.reply) ? [ev('h', 'hset', x.args[0])] : []),
  hsetnx: (x) => (x.reply === 1 ? [ev('h', 'hset', x.args[0])] : []),
  hdel: same('h', 'hdel'),
  hincrby: (x) => (ok(x.reply) ? [ev('h', 'hincrby', x.args[0])] : []),
  hincrbyfloat: (x) => (ok(x.reply) ? [ev('h', 'hincrbyfloat', x.args[0])] : []),
  hgetdel: (x) => (Array.isArray(x.reply) && x.reply.some((r) => r !== null) ? withDel([ev('h', 'hdel', x.args[0])], x, x.args[0]) : []),
  hexpire: (x) => fieldTtlEvents(x),
  hpexpire: (x) => fieldTtlEvents(x),
  hexpireat: (x) => fieldTtlEvents(x),
  hpexpireat: (x) => fieldTtlEvents(x),
  hpersist: (x) => (Array.isArray(x.reply) && x.reply.includes(1) ? [ev('h', 'hpersist', x.args[0])] : []),
  hsetex: (x) => {
    if (x.reply !== 1) return [];
    const out = [ev('h', 'hset', x.args[0])];
    if (x.args.some((a) => /^(ex|px|exat|pxat)$/i.test(a))) out.push(ev('h', 'hexpire', x.args[0]));
    return out;
  },
  hgetex: (x) => {
    if (!Array.isArray(x.reply) || !x.reply.some((r) => r !== null)) return [];
    const opt = x.args.find((a) => /^(ex|px|exat|pxat|persist)$/i.test(a));
    if (!opt) return [];
    if (!x.existsAfter(x.args[0])) return withDel([ev('h', 'hdel', x.args[0])], x, x.args[0]);
    return [ev('h', opt.toLowerCase() === 'persist' ? 'hpersist' : 'hexpire', x.args[0])];
  },

  // ---- sets ----
  sadd: same('s', 'sadd'),
  srem: same('s', 'srem'),
  spop: (x) => (ok(x.reply) && !(Array.isArray(x.reply) && x.reply.length === 0) ? withDel([ev('s', 'spop', x.args[0])], x, x.args[0]) : []),
  smove: (x) => (x.reply === 1 ? withDel([ev('s', 'srem', x.args[0])], x, x.args[0]).concat(ev('s', 'sadd', x.args[1])) : []),
  sinterstore: (x) => storeEvents(x, 's', 'sinterstore'),
  sunionstore: (x) => storeEvents(x, 's', 'sunionstore'),
  sdiffstore: (x) => storeEvents(x, 's', 'sdiffstore'),

  // ---- sorted sets ----
  zadd: (x) => {
    if (!ok(x.reply) || x.reply === 0 && !x.existsAfter(x.args[0])) return [];
    const incr = x.args.slice(1, 7).some((a) => a.toLowerCase() === 'incr');
    return [ev('z', incr ? 'zincr' : 'zadd', x.args[0])];
  },
  zincrby: (x) => (ok(x.reply) ? [ev('z', 'zincr', x.args[0])] : []),
  zrem: same('z', 'zrem'),
  zremrangebyscore: same('z', 'zrembyscore'),
  zremrangebyrank: same('z', 'zrembyrank'),
  zremrangebylex: same('z', 'zrembylex'),
  zpopmin: (x) => (Array.isArray(x.reply) && x.reply.length ? withDel([ev('z', 'zpopmin', x.args[0])], x, x.args[0]) : []),
  zpopmax: (x) => (Array.isArray(x.reply) && x.reply.length ? withDel([ev('z', 'zpopmax', x.args[0])], x, x.args[0]) : []),
  bzpopmin: (x) => popEvents(x, 'z', 'zpopmin'),
  bzpopmax: (x) => popEvents(x, 'z', 'zpopmax'),
  zmpop: (x) => mpopEvents(x, 'z', (a) => (a.toLowerCase() === 'min' ? 'zpopmin' : 'zpopmax'), 1),
  bzmpop: (x) => mpopEvents(x, 'z', (a) => (a.toLowerCase() === 'min' ? 'zpopmin' : 'zpopmax'), 2),
  zunionstore: (x) => storeEvents(x, 'z', 'zunionstore'),
  zinterstore: (x) => storeEvents(x, 'z', 'zinterstore'),
  zdiffstore: (x) => storeEvents(x, 'z', 'zdiffstore'),
  zrangestore: (x) => storeEvents(x, 'z', 'zrangestore'),
  geoadd: (x) => (ok(x.reply) && x.existsAfter(x.args[0]) ? [ev('z', 'zadd', x.args[0])] : []),

  // ---- streams ----
  xadd: (x) => {
    if (!ok(x.reply)) return [];
    const out = [ev('t', 'xadd', x.args[0])];
    // xtrim follows only when the trimming option really removed entries
    const key = x.args[0];
    const trimmed = x.sizeBefore && x.sizeAfter ? x.sizeAfter(key) < x.sizeBefore(key) + 1 : x.args.some((a) => /^(maxlen|minid)$/i.test(a));
    if (trimmed && x.args.some((a) => /^(maxlen|minid)$/i.test(a))) out.push(ev('t', 'xtrim', key));
    return out;
  },
  xdel: same('t', 'xdel'),
  xtrim: same('t', 'xtrim'),
  xsetid: (x) => (ok(x.reply) ? [ev('t', 'xsetid', x.args[0])] : []),
  xgroup: (x) => {
    const sub = (x.args[0] ?? '').toLowerCase();
    // DELCONSUMER replies the consumer's pending count, which may be 0
    if (!ok(x.reply) || (x.reply === 0 && sub !== 'delconsumer')) return [];
    const names: Record<string, string> = {
      create: 'xgroup-create',
      createconsumer: 'xgroup-createconsumer',
      delconsumer: 'xgroup-delconsumer',
      destroy: 'xgroup-destroy',
      setid: 'xgroup-setid',
    };
    return names[sub] ? [ev('t', names[sub], x.args[1])] : [];
  },
};

function expireEvents(x: Execution): KeyEvent[] {
  if (x.reply !== 1) return [];
  // A time in the past deletes the key: Redis then emits `del` instead of `expire`.
  return [ev('g', x.existsAfter(x.args[0]) ? 'expire' : 'del', x.args[0])];
}

function fieldTtlEvents(x: Execution): KeyEvent[] {
  if (!Array.isArray(x.reply)) return [];
  const out: KeyEvent[] = [];
  if (x.reply.includes(1)) out.push(ev('h', 'hexpire', x.args[0]));
  if (x.reply.includes(2)) out.push(ev('h', 'hdel', x.args[0]));
  return withDel(out, x, x.args[0]);
}

function popEvents(x: Execution, cls: string, event: string): KeyEvent[] {
  if (!Array.isArray(x.reply) || typeof x.reply[0] !== 'string') return [];
  const key = x.reply[0];
  return withDel([ev(cls, event, key)], x, key);
}

function mpopEvents(x: Execution, cls: string, eventFor: (side: string) => string, numkeysAt: number): KeyEvent[] {
  if (!Array.isArray(x.reply) || typeof x.reply[0] !== 'string') return [];
  const n = Number(x.args[numkeysAt - 1]);
  const side = x.args[numkeysAt + n] ?? '';
  const key = x.reply[0];
  return withDel([ev(cls, eventFor(side), key)], x, key);
}

function moveEvents(x: Execution, popEvent: string, pushEvent: string): KeyEvent[] {
  if (!ok(x.reply)) return [];
  return withDel([ev('l', popEvent, x.args[0])], x, x.args[0]).concat(ev('l', pushEvent, x.args[1]));
}

function storeEvents(x: Execution, cls: string, event: string): KeyEvent[] {
  const dst = x.args[0];
  if (x.existsAfter(dst)) return [ev(cls, event, dst)];
  return x.existedBefore(dst) ? [ev('g', 'del', dst)] : [];
}

/** Events for one executed command (without the `new` / `keymiss` / `expired` / `evicted` classes, which the server adds itself). */
export function keyspaceEvents(x: Execution): KeyEvent[] {
  if (x.reply instanceof RespError) return [];
  const emit = EMITTERS[x.name];
  return emit ? emit(x) : [];
}

/** Parsed notify-keyspace-events flags. */
export interface NotifyFlags {
  keyspace: boolean;
  keyevent: boolean;
  classes: Set<string>;
}

export function parseNotifyFlags(value: string): NotifyFlags {
  const classes = new Set<string>();
  for (const c of value) {
    if (c === 'A') for (const a of 'g$lshzxetd') classes.add(a);
    else if (c !== 'K' && c !== 'E') classes.add(c);
  }
  return { keyspace: value.includes('K'), keyevent: value.includes('E'), classes };
}

/** The pub/sub messages Redis publishes for one event: `__keyspace@<db>__:<key>` → event, `__keyevent@<db>__:<event>` → key. */
export function notificationMessages(flags: NotifyFlags, db: number, e: KeyEvent): Array<[string, string]> {
  if (!flags.classes.has(e.cls)) return [];
  const out: Array<[string, string]> = [];
  if (flags.keyspace) out.push([`__keyspace@${db}__:${e.key}`, e.event]);
  if (flags.keyevent) out.push([`__keyevent@${db}__:${e.event}`, e.key]);
  return out;
}

/** Commands that read keys and therefore can emit `keymiss` (class m) for missing keys. */
export function isReadCommand(flags: { write?: boolean } | undefined): boolean {
  return !flags?.write;
}
